import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"Terminal: introduccion y navegacion","description":"","frontmatter":{},"headers":[],"relativePath":"herramientas/terminal/01-introduccion-y-navegacion.md","filePath":"herramientas/terminal/01-introduccion-y-navegacion.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"herramientas/terminal/01-introduccion-y-navegacion.md"};function n(r,a,d,l,c,h){return i(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="terminal-introduccion-y-navegacion" tabindex="-1">Terminal: introduccion y navegacion <a class="header-anchor" href="#terminal-introduccion-y-navegacion" aria-label="Permalink to &quot;Terminal: introduccion y navegacion&quot;">​</a></h1><p>La terminal es la interfaz de texto con el sistema operativo. Dominala acelera Git, Docker, SSH, builds y diagnostico: casi todas las herramientas DevOps nacieron primero como CLI.</p><p>Este manual usa sintaxis compatible con <strong>Bash</strong> (Linux/macOS y Git Bash en Windows). En PowerShell los equivalentes existen, pero los ejemplos priorizan Bash por ser el comun denominador en servidores.</p><h2 id="capitulos" tabindex="-1">Capitulos <a class="header-anchor" href="#capitulos" aria-label="Permalink to &quot;Capitulos&quot;">​</a></h2><ol><li><a href="./01-introduccion-y-navegacion">Introduccion y navegacion</a></li><li><a href="./02-archivos-busqueda-y-texto">Archivos busqueda y texto</a></li><li><a href="./03-redirecciones-pipes-y-variables">Redirecciones pipes y variables</a></li><li><a href="./04-scripts-basicos">Scripts basicos</a></li><li><a href="./05-diagnostico-y-trabajo-remoto">Diagnostico y trabajo remoto</a></li></ol><h2 id="anatomia-del-prompt" tabindex="-1">Anatomia del prompt <a class="header-anchor" href="#anatomia-del-prompt" aria-label="Permalink to &quot;Anatomia del prompt&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usuario@host:~/proyectos$</span></span></code></pre></div><p>Escribes un comando + Enter. El shell busca el ejecutable en <code>$PATH</code>, lo lanza y muestra la salida.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whoami</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hola&quot;</span></span></code></pre></div><h2 id="navegacion-esencial" tabindex="-1">Navegacion esencial <a class="header-anchor" href="#navegacion-esencial" aria-label="Permalink to &quot;Navegacion esencial&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Que hace</th></tr></thead><tbody><tr><td><code>pwd</code></td><td>Directorio actual</td></tr><tr><td><code>ls</code></td><td>Lista entradas</td></tr><tr><td><code>ls -la</code></td><td>Incluye ocultos y detalles</td></tr><tr><td><code>cd ruta</code></td><td>Cambia de directorio</td></tr><tr><td><code>cd ..</code></td><td>Sube un nivel</td></tr><tr><td><code>cd ~</code> o <code>cd</code></td><td>Va al home</td></tr><tr><td><code>cd -</code></td><td>Vuelve al directorio anterior</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/proyectos/manuales</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span></span></code></pre></div><p>Rutas:</p><ul><li><strong>Absolutas</strong>: empiezan por <code>/</code> (Linux/macOS) — <code>/var/log/nginx</code></li><li><strong>Relativas</strong>: desde donde estas — <code>./src</code> , <code>../README.md</code></li></ul><h2 id="atajos-que-ahorran-horas" tabindex="-1">Atajos que ahorran horas <a class="header-anchor" href="#atajos-que-ahorran-horas" aria-label="Permalink to &quot;Atajos que ahorran horas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Atajo</th><th>Efecto</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>Autocompletar</td></tr><tr><td><code>Ctrl+C</code></td><td>Cancelar proceso en primer plano</td></tr><tr><td><code>Ctrl+L</code> o <code>clear</code></td><td>Limpiar pantalla</td></tr><tr><td><code>Ctrl+R</code></td><td>Buscar en historial</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>Recorrer historial</td></tr><tr><td><code>Ctrl+A</code> / <code>Ctrl+E</code></td><td>Inicio / fin de linea</td></tr><tr><td><code>Ctrl+U</code></td><td>Borrar desde el cursor al inicio</td></tr></tbody></table><h2 id="ayuda-integrada" tabindex="-1">Ayuda integrada <a class="header-anchor" href="#ayuda-integrada" aria-label="Permalink to &quot;Ayuda integrada&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copy</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # buscar en paginas man</span></span></code></pre></div><h2 id="windows-que-terminal-usar" tabindex="-1">Windows: que terminal usar <a class="header-anchor" href="#windows-que-terminal-usar" aria-label="Permalink to &quot;Windows: que terminal usar&quot;">​</a></h2><ul><li><strong>Git Bash</strong> o <strong>WSL</strong>: maxima compatibilidad con ejemplos Linux.</li><li><strong>PowerShell</strong>: nativo Windows; comandos distintos (<code>Get-ChildItem</code> vs <code>ls</code>).</li><li><strong>cmd.exe</strong>: legacy; evitalo para trabajo moderno.</li></ul><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Confundir <code>\\</code> de Windows con <code>/</code> de Bash.</li><li>Olvidar que <code>~</code> no se expande igual dentro de comillas simples.</li><li>Ejecutar <code>cd</code> en un subshell de un script y esperar que cambie tu shell padre.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas practicas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas practicas&quot;">​</a></h2><ul><li>Trabaja siempre sabiendo el <code>pwd</code>.</li><li>Prefiere rutas relativas dentro de un repo.</li><li>Usa Tab; no teclees rutas largas a mano.</li><li>En equipo, documenta si los scripts asumen Bash o PowerShell.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Abre la terminal y navega hasta un proyecto con solo <code>cd</code> y <code>ls</code>.</li><li>Lista ocultos con <code>ls -la</code> y localiza <code>.git</code> si existe.</li><li>Usa <code>cd -</code> para alternar entre dos carpetas.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continua con <a href="./02-archivos-busqueda-y-texto">Archivos busqueda y texto</a>.</p>`,28)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
